import abc
import logging
import re
import sys

import six

from . import instance_loader, logger
from .config import Config
from .exceptions import AbstractUeLibException, ConfigurationNotDefined, RequiredDeviceNotFound, \
    UnknownDevice, PoolCreationError
from .plugin import load_classes_implemented_by_plugins

CAPABILITIES = "CAPABILITIES"


def check_device_capabilities(device_config, req_caps):
    """
    Checks whether given device config has required capabilities.

    :param device_config: Device Configuration
    :param req_caps: List of Required Capabilities
    :return: Boolean. True if Device has required capabilities, otherwise False
    """
    device_caps = get_capabilities(device_config)
    logger.debug(f'Device capabilities: {device_caps}')
    return check_required_capabilities(req_caps, device_caps)


def get_capabilities(configuration):
    """
    Gets capabilities from device configuration dictionary.

    :param configuration: Device configuration
    :return: list of found capabilities from the configuration. If capabilities is not defined empty list is returned
    """
    if CAPABILITIES in configuration:
        return configuration[CAPABILITIES]
    return []


def check_required_capabilities(required_caps, device_caps):
    """
    Checks if device_caps fulfils all requred_caps.

    :param required_caps: List of required capabilities, None or empty list as a value
                          returns always True. Other types are converted to single item list
    :param device_caps: List of  DeviceCapabilities
    :return: Boolean True if Device fulfils required capabilities
                     False if required capabilities are not fulfilled
    """
    if isinstance(required_caps, list):
        capab_set = set(required_caps)
    elif required_caps is None:
        capab_set = set()
    else:
        capab_set = {required_caps}
    device_capab_set = set(device_caps)
    return capab_set.issubset(device_capab_set)


@six.add_metaclass(abc.ABCMeta)
class DevicePool:
    """
    Specific pools don't need to be derived classed. They may differ in constructor signature.
    Expected behaviour is to have _get_device() method that either finds Device fulfilling specified
    requirements or raises informative exception.
    Pool should track the reserved device's, that it doesn't give the same device twice for different alias.
    """
    def __init__(self):
        """Allowed constructor with any signature."""
        pass  # pylint: disable=unnecessary-pass

    @abc.abstractmethod
    def _get_device(self, device_characteristics):
        """
        Return Device instance fulfilling requirements. (public API)
        :return: device instance
        :raises: :py:class:`ute_common_abstract_core.exceptions.RequiredDeviceNotFound`: If matching device is not found
        """
        pass  # pylint: disable=unnecessary-pass

    @abc.abstractmethod
    def _release_device(self, device):
        """
        Allow Device to be reused - it should be in pool of available Devices. (public API)
        :raises: :py:class:`ute_common_abstract_core.exceptions.UnknownDevice`: If given device has not been returned from this pool via _get_device()
        :return: None
        """
        pass  # pylint: disable=unnecessary-pass

    def shutdown(self):
        """Releases all resources used by this pool and Devices in this pool."""
        pass  # pylint: disable=unnecessary-pass


@six.add_metaclass(abc.ABCMeta)
class DeviceActivePools(DevicePool):
    """Container of all DevicePools active on given Testline"""

    def __init__(self, device_pool_type):
        """
        Basic initialization.

        :param device_pool_type:
        """
        super(DeviceActivePools, self).__init__()
        self.logger = logging.getLogger('al.devicepool')
        self.console_warning = logging.getLogger('root').warning
        self._active_pools = []
        self.device_pool_type = device_pool_type
        self.known_plugin_devicepools = load_classes_implemented_by_plugins(classes_group=self.device_pool_type,
                                                                            logger=self.logger)
        self._pool_that_created_device = {}  # key is id(Device-object), value is pool that has created Device-object
        self._device_pools_configuration = self.get_active_pools_configuration()
        if self._device_pools_configuration is not None:
            logger.debug(f'device_pools_configuration: {self._device_pools_configuration}')
            self.logger.debug(f"{self} loaded configuration: {self._device_pools_configuration}")
            self._active_pools = self.create_active_pools(self._device_pools_configuration)
            self.logger.debug(f"{self} will use following pools: {self._active_pools}")
        else:  # for robot dryrun purposes on UTE Cloud, as robot dryrun is not executing on real testline
            logger.debug(f'Empty {self.device_pool_type} Configuration')
            self.logger.debug(f"{self} has empty configuration")

    def __str__(self):
        return f"{self.__class__.__name__}({self.device_pool_type})"

    def create_active_pools(self, device_pools_configuration):
        """
        Create devicepools which given testline defines as active/needed
        :param device_pools_configuration: pools configuration on given testline
        :return: list of active pools
        """
        active_pools = []
        for device_pool_name, device_pool_params in device_pools_configuration.items():
            active_pool_class, err = self.get_pool_class(pool_name=device_pool_name)
            if active_pool_class is None:
                self._device_pools_configuration[device_pool_name]['creation'] = False
                self._device_pools_configuration[device_pool_name]['error'] = err
                continue

            # we do have pool class here, let's create pool instance
            active_pool, err = self.create_pool(pool_class=active_pool_class, pool_params=device_pool_params)
            if active_pool:
                active_pools.append(active_pool)
            else:
                self._device_pools_configuration[device_pool_name]['creation'] = False
                self._device_pools_configuration[device_pool_name]['error'] = err

        return active_pools

    def get_pool_class(self, pool_name):
        """
        Get class of pool either from plugins or name-to-classfullname mapping

        :param pool_name:
        :return: class object of pool
        """
        self.logger.debug("Creating {} class via {}".format(pool_name, "Plugin system"))
        pool_class = self.get_pool_class_from_plugins(pool_name)
        err = None
        if pool_class is None:
            wrn_msg = "Creating {} class via {} failed.".format(pool_name, "Plugin system")
            self.logger.warning(wrn_msg)
            self.console_warning(wrn_msg)
            # fallback to old way
            pool_class_fullname = self.get_pool_class_fullname(pool_name)
            self.logger.debug(f"Trying create {pool_name} class via {pool_class_fullname}")
            try:
                pool_class = instance_loader.load_class_from_class_fullname(class_fullname=pool_class_fullname)
            # we intentionally catch all exceptions
            # since we don't want nonexisting/incorrect pool-class to break whole abstract lib core
            except Exception as error:  # pylint: disable=broad-except
                err = '{}({})'.format(error.__repr__().split('(')[0], error)
                msg = f"Will not use {pool_name}"
                wrn_msg = f"Creating {pool_name} class via {pool_class_fullname} failed. {msg}\n{error!r}"
                self.logger.warning(wrn_msg)
                self.console_warning(wrn_msg)
        self.logger.debug(f"Created {pool_class}")
        return pool_class, err

    def create_pool(self, pool_class, pool_params):
        """
        Create instance of pool from pool class and its constructor parameters

        :param pool_class:
        :param pool_params:
        :return: instance of pool
        """
        pool_name = pool_class.__name__
        pool_class_fullname = f"{pool_class.__module__}.{pool_name}"
        self.logger.debug(f"Creating {pool_name} via {pool_class_fullname}({pool_params})")
        err = None
        try:
            pool = instance_loader.create_class_instance(class_object=pool_class,
                                                         constructor_params=pool_params)
            self.logger.debug(f"Created  {pool}")
            logger.info(f'DeviceActivePools initialization: Device pool {pool_class_fullname} created')
        # we intentionally catch all exceptions
        # since we don't want nonexisting/incorrect pool-instance to break whole abstract lib core
        except Exception as error:  # pylint: disable=broad-except
            err = '{}({})'.format(error.__repr__().split('(')[0], error)
            err_msg = f"Failed creation {pool_class_fullname}(), error: {err}"
            wrn_msg = f'Device pool creation failed for {pool_class_fullname}'
            self.console_warning(wrn_msg)
            logger.warning(wrn_msg)
            self.logger.error(err_msg)
            pool = None
        return pool, err

    def get_pool_class_from_plugins(self, device_pool_name):
        """
        Return pool class if it is provided by any plugin

        :param device_pool_name:
        :return: class of pool
        """
        if device_pool_name in self.known_plugin_devicepools:
            return self.known_plugin_devicepools[device_pool_name]
        return None

    def get_active_pools_configuration(self):
        """
        Configuration of all <device_pool_type> Pools active on given Testline.

        :return: active pools config
        """
        device_pools_configuration = Config().get_config(section=self.device_pool_type)
        if not device_pools_configuration:
            raise ConfigurationNotDefined(f'{self.device_pool_type} not defined, please use ABSTRACT_LIB_CONFIG variable to define it. \n '
                                          'It can be defined either as a robot variable or as a system environment variable')
        return device_pools_configuration

    def get_pool_class_fullname(self, device_pool_name):
        """
        Ensure we have full package.module.class name for given DevicePool
        :param device_pool_name: DevicePool type or fullname
        :return: full package.module.class name
        """
        if "." in device_pool_name:
            pool_class_fullname = device_pool_name
        else:
            pool_type = device_pool_name
            pool_class_fullname = self.convert_pool_type_2_pool_class_fullname(pool_type)
        return pool_class_fullname

    def convert_pool_type_2_pool_class_fullname(self, pool_type):
        """
        Encapsulate convention how to produce full package.module.class name for given DevicePool type
        :param pool_type: DevicePool type
        :return: full package.module.class name
        """
        raise NotImplementedError

    def _get_failed_pool_creation_msg(self):
        err_log = 'Failed creation:'
        for pool, params in self._device_pools_configuration.items():
            if params['creation'] is False:
                err_log = '{}\n-{}, error: {}'.format(err_log, pool, params['error'])
        return err_log

    def _get_device(self, device_characteristics):
        """
        Return Device instance fulfilling requirements.
        Redirects the query to active pools
        :return: device instance, first matching one returned by any active pool
        :raises: :py:class:`ute_common_abstract_core.exceptions.ConfigurationNotDefined`: If Device configuration cannot be found
        :raises: :py:class:`ute_common_abstract_core.exceptions.RequiredDeviceNotFound`: If matching device is not found
        """
        if not self._active_pools:
            self.logger.error(f"{self}: has no active pool")
            err_log = self._get_failed_pool_creation_msg()
            raise PoolCreationError(f'None of {self.device_pool_type} has been created.\n{err_log}')

        for (idx, device_pool) in enumerate(self._active_pools):
            logger.debug('DeviceActivePools: current pool in search:' + str(device_pool.__class__.__name__))
            try:
                device = device_pool._get_device(device_characteristics)
                self._remember_device_creating_pool(device, device_pool)
                self.logger.debug(f"{self}: {device} taken from   {device_pool}")
                return device
            except RequiredDeviceNotFound as exc:
                if (idx + 1) == len(self._active_pools):
                    self.logger.error(f"{self}: {exc!r}")
                    raise  # it is 'not found' inside last pool

    def _release_device(self, device):
        """
        Allow Device to be reused - it should be in pool of available Devices.
        :return: None
        """
        if id(device) in self._pool_that_created_device:
            device_creating_pool = self._pool_that_created_device[id(device)]
            self.logger.debug(f"{self}: {device} returning to {device_creating_pool}")
            device_creating_pool._release_device(device)
        else:
            exc = UnknownDevice(f"'{device}' Device has not been withdrawn from device-pool or it has been already released to device-pool")
            self.logger.error(f"{self}: {exc!r}")
            raise exc

    def _remember_device_creating_pool(self, device, device_pool):
        self._pool_that_created_device[id(device)] = device_pool

    def shutdown(self):
        """Shutdown"""
        self.logger.debug(f"{self} shutting down all active pools")
        for pool in self._active_pools:
            pool.shutdown()
        self.logger.debug(f"{self} all active pools are down")


@six.add_metaclass(abc.ABCMeta)
class CfgFileBasedDevicePool(DevicePool):
    """Configuration File Based Device Pool"""
    def __init__(self, config_file_path=None, inline_config=None):
        """
        Basic initialization.

        :param config_file_path:
        :param inline_config:
        """
        super(CfgFileBasedDevicePool, self).__init__()
        if inline_config is None:
            inline_config = {}
        self.logger = logging.getLogger('al.devicepool')
        cfg_logger = logging.getLogger('al.config')
        self.console_warning = logging.getLogger('root').warning
        if config_file_path is not None:
            config_file_abspath = Config().resolve_config_abspath(config_file_path)
            cfg_logger.debug(f"reading device config from: {config_file_abspath}")
            self._device_configuration = self._read_device_configuration(config_file_abspath)
        else:
            self._device_configuration = {}
        if self._device_configuration is not None:
            # happens in: test_DeviceActivePools_creates_correct_device_pool_based_on_configuration
            cfg_logger.debug(f"updating device config from inline_config: {inline_config}")
            self._device_configuration.update(inline_config)
        self._taken_devices = {}
        self.logger.debug(f"{self.__class__.__name__}(config_file_path={config_file_path}, inline_config={inline_config})")
        self.logger.debug(f"{self.__class__.__name__} loaded configuration: {self._device_configuration}")

    def _read_device_configuration(self, config_file_path):
        """
        Reads Devices configuration file
        :param config_file_path: location of file describing Devices
        :return: Device configuration as python dict
        """
        device_configuration = Config().read_yaml_configfile(config_file_path)
        return device_configuration

    def _get_device(self, device_characteristics):
        """
        Return Device instance fulfilling requirements
        :param device_characteristics: description of what is required from device
        :return: device instance, that matches given search criteria
        :raises: :py:class:`ute_common_abstract_core.exceptions.RequiredDeviceNotFound`: If matching device is not found
        """
        self.logger.debug(f'{self}: searching by {device_characteristics}')
        device_characteristics.ensure_not_empty()
        (device_name, device) = self._search_configuration_by_requirements(device_characteristics)
        self._withdraw_device_from_available_devices(device_name, device)
        self.logger.info(f"{self}: {device_name}/{device} taken from pool")
        return device

    def _release_device(self, device):
        """
        Allow Device to be reused - it should be in pool of available Devices.
        :return: None
        """
        for (taken_device_name, taken_device) in self._taken_devices.items():
            if taken_device is device:
                self._return_device_to_available_devices(taken_device_name)
                self.logger.info(f"{self}: {taken_device_name}/{taken_device} returned to pool")
                return
        exc = UnknownDevice(f"'{device}' Device has not been withdrawn from this device-pool or it has been already released to device-pool")
        self.logger.error(f"{self}: {exc!r}")
        raise exc

    def _search_configuration_by_requirements(self, device_characteristics):
        capabilities = device_characteristics.domain_capabilities
        logger.debug(f'required capabilities in search: {capabilities}')
        devices_to_take = self._available_devices()
        self.logger.debug(f'Searching device fulfilling {device_characteristics} - search within {devices_to_take}')
        last_create_exception = None
        last_create_exception_stacktrace = None
        for device_name in devices_to_take:
            logger.debug(f'current Device in search: {device_name}')
            device_config = self._get_device_config_by_name(device_name)
            variants_configs = self._prepare_device_variants_configs(device_config, device_name)
            for variant_config in variants_configs:
                if self._has_matching_characteristics(variant_config, device_characteristics):
                    self.logger.debug(f'{device_characteristics} found as {device_name} - {variant_config}')
                    try:
                        device = self._create_device_with_backward_compatibility(device_name, variant_config)
                        logger.debug(f'{device_characteristics} found as Device({device_name}: {variant_config})')
                        return (device_name, device)
                    except (ImportError, AbstractUeLibException) as err:
                        last_create_exception = err
                        last_create_exception_stacktrace = sys.exc_info()[2]
                        self.logger.error(f'Device {device_name} creation failed:')
                        self.logger.exception(err)
                        logger.error(f'Device creation did not succeeded: {device_name}')
                        logger.exception(last_create_exception)
                        continue
        self.logger.debug(f'Device fulfilling {device_characteristics} not found within {devices_to_take}')
        logger.debug(f'Requirements {str(device_characteristics)} not found from configuration {devices_to_take}')
        exception = RequiredDeviceNotFound(device_characteristics)
        if last_create_exception:
            exception.__cause__ = last_create_exception  # https://www.python.org/dev/peps/pep-0344/
        six.reraise(RequiredDeviceNotFound, exception, last_create_exception_stacktrace)

    def _prepare_device_variants_configs(self, device_config, device_name):
        if self._device_has_variants(device_config):
            logger.debug(f'Searching within VARIANTS of device: {device_name}')
            variants_configs = self._get_variants_configurations(device_config)
        else:
            logger.debug(f'Device: {device_name} has no VARIANTS')
            variants_configs = [device_config]
        return variants_configs

    def _device_has_variants(self, device_config):
        return True if 'VARIANTS' in device_config else False

    def _get_variants_configurations(self, device_config):
        variants_config = []
        class_param = {'CLASS': device_config['CLASS']}
        for v_config in device_config['VARIANTS']:
            v_config.update(class_param)
            variants_config.append(v_config)
        return variants_config

    def _create_device_with_backward_compatibility(self, device_name, device_config):
        if hasattr(self, '_create_device'):  # backward compatibility
            device = self._create_device(device_name, device_config)
        else:
            device = self.create_device(device_name, device_config)
        return device

    def _has_matching_characteristics(self, device_config, device_characteristics):
        capabilities = device_characteristics.domain_capabilities
        if check_device_capabilities(device_config, capabilities):
            return True
        return False

    def _get_device_config_by_name(self, device_name):
        return self._device_configuration[device_name]

    def create_device(self, device_name, device_config):
        """
        Create instance of device

        :param device_name:
        :param device_config:
        :return: device instance
        """
        device_class = self.get_device_class(class_name=device_config['CLASS'])

        # we do have device class here, let's create device instance
        constructor_params = {'name': device_name}
        constructor_params.update(device_config['CONSTRUCTOR_PARAMETERS'])
        device = instance_loader.create_class_instance(class_object=device_class,
                                                       constructor_params=constructor_params)
        return device

    def get_device_class(self, class_name):
        """
        Return class for specified class_name

        :param class_name:
        :return: class object
        """
        try:
            device_class_fullname = self.get_device_class_fullname(class_name)
        except Exception as err:
            reason = f"unknown full package.class name of {class_name}"
            err_msg = f"Creating {class_name} class failed - {reason}. Caught {err!r}"
            self.logger.warning(err_msg)
            self.console_warning(err_msg)
            raise AbstractUeLibException(err_msg)

        try:
            self.logger.debug(f"Creating {class_name} class via {device_class_fullname}")
            device_class = instance_loader.load_class_from_class_fullname(class_fullname=device_class_fullname)
        # we intentionally catch all exceptions
        # since we don't want nonexisting/incorrect pool-class to break whole abstract lib core
        except Exception as err:
            wrn_msg = f"Creating {class_name} class via {device_class_fullname} failed - reason: {err!r}"
            self.logger.warning(wrn_msg)
            self.console_warning(wrn_msg)
            err_msg = f"{class_name} can't be loaded from {device_class_fullname} - reason: {err!r}"
            raise AbstractUeLibException(err_msg)
        return device_class

    @classmethod
    def get_device_class_fullname(cls, class_name):
        """
        Ensure we have full package.module.class name for given Device
        :param class_name: Device type or fullname
        :return: full package.module.class name
        """
        if "." in class_name:  # TODO: do we allow this for advanced users aware what they do?
            device_class_fullname = class_name
        else:
            device_type = class_name
            device_class_fullname = cls.convert_device_type_2_device_class_fullname(device_type)
        return device_class_fullname

    @classmethod
    def convert_device_type_2_device_class_fullname(cls, device_type):
        """
        Encapsulate convention how to produce full package.module.class name for given Device type

        Default convention is as follows::
          - take package name from cls (which is device pool), f.ex.:
            ta_ue_plugin_android.ue.android.androiduepool:AndroidUePool --> ta_ue_plugin_android.ue.android
            (means: we expect device module in same package as devicepool module)
          - take module name from device_type converting CamelCase to underscored_parts, f.ex.:
            AndroidUe --> android_ue
          - take class name 1:1 from device_type, f.ex.:
            AndroidUe --> AndroidUe
          - concatenate above 3 parts, f.ex.:
            ta_ue_plugin_android.ue.android.android_ue.AndroidUe

        Derived classes should overwrite this method if default convention doesn't fit their needs.

        :param device_type: Device type (must be CamelCase name)
        :return: full package.module.class name
        """
        assert '_' not in device_type
        package_name = cls.__module__.rpartition('.')[0]
        camelcase2underscore = re.compile('((?<=[a-z0-9])[A-Z]|(?!^)[A-Z](?=[a-z]))')
        module_name = camelcase2underscore.sub(r'_\1', device_type).lower()
        class_fullname = f'{package_name}.{module_name}.{device_type}'
        return class_fullname

    def _available_devices(self):
        """
        Return Device-names possible to use
        :return: list of Device names
        """
        return [device_name for device_name in self._device_configuration.keys() if device_name not in self._taken_devices]

    def _withdraw_device_from_available_devices(self, device_name, device):
        """
        Device starts to be used - it should not be in pool of available Devices.
        :return: None
        """
        self._taken_devices[device_name] = device

    def _return_device_to_available_devices(self, device_name):
        """
        Device no more used - it should be back in pool of available Devices.
        :return: None
        """
        del self._taken_devices[device_name]
